	return next
}

// skip_locked makes the lock one that leaves out the rows other transactions locked.
pub fn (q OwnedPetQuery) skip_locked() OwnedPetQuery {
	mut next := q
	next.query = load.Query{
		...q.query
		lock: load.Lock{
			...q.query.lock
			skip_locked: true
		}
	}
	return next
}

