// OwnedPetGroupBy groups the rows of a `OwnedPetQuery`. Start one with `group_by`.
pub struct OwnedPetGroupBy {
	query OwnedPetQuery
pub:
	columns    []string
	aggregates []load.Aggregate
}

// group_by groups the matching rows by `columns`. It needs a vgraph driver.
pub fn (q OwnedPetQuery) group_by(columns ...string) OwnedPetGroupBy {
	return OwnedPetGroupBy{
		query:   q
		columns: columns
	}
}

// aggregate adds what each group gets, such as `vgraph.count()` or
// `vgraph.sum('views')`.
pub fn (g OwnedPetGroupBy) aggregate(aggregates ...load.Aggregate) OwnedPetGroupBy {
	mut all := g.aggregates.clone()
	all << aggregates
	return OwnedPetGroupBy{
		...g
		aggregates: all
	}
}

// all returns the groups, ordered by their columns.
pub fn (g OwnedPetGroupBy) all() ![]load.Group {
	q := g.query
	return load.group_where(q.graph.client.conn, 'pet_owners', q.graph.client.prepare_query('pet_owners', q.query)!, g.columns.map(load.GroupColumn{
		name: it
		typ:  owned_pet_column_type(it)
	}), g.aggregates)
}

// scan reads the groups into `T`, by name: its fields named after the grouped
// columns and the aggregates (`count`, `sum_views`).
pub fn (g OwnedPetGroupBy) scan[T]() ![]T {
	return load.scan_groups[T](g.all()!)
}

// owned_pet_column_type returns the V type of a column of `pet_owners`.
fn owned_pet_column_type(column string) string {
	return match column {
		'id' { 'int' }
		'pet_name' { 'string' }
		'owner_id' { 'int' }
		'owner_name' { 'string' }
		else { '' }
	}
}

// order_by_owner_spouse_id orders the rows by the `spouse_id` of their `owner`.
pub fn (q OwnedPetQuery) order_by_owner_spouse_id() OwnedPetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."spouse_id" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
	})
}

// order_by_owner_spouse_id_desc orders the rows by the `spouse_id` of their
// `owner`, descending.
pub fn (q OwnedPetQuery) order_by_owner_spouse_id_desc() OwnedPetQuery {
	return q.order_by(load.Order{
		expr: '(SELECT "t1"."spouse_id" FROM "users" AS "t1" WHERE "t1"."id" = "t0"."owner_id")'
		desc: true
	})
}

// with_owner loads each row's `owner` (many_to_one `users`) with it, in one
// query for all the rows. `configure` narrows them, and can load their edges.
pub fn (q OwnedPetQuery) with_owner(configure ...fn (UserQuery) UserQuery) OwnedPetQuery {
	mut next := q
	next.with_owner = true
	next.owner_fns = configure
	return next
}

// all returns the matching rows, with the requested edges.
pub fn (q OwnedPetQuery) all() ![]OwnedPetNode {
	rows := load.select_where[models.OwnedPet](q.graph.client.conn, q.graph.client.prepare_query('pet_owners', q.query)!)!
	return q.nodes(rows)
}

// first returns the first matching row, with the requested edges, or a
// `NotFoundError`.
pub fn (q OwnedPetQuery) first() !OwnedPetNode {
	nodes := q.limit(1).all()!
	if nodes.len == 0 {
		return NotFoundError{
			table: 'pet_owners'
		}
	}
	return nodes[0]
}

// nodes loads the requested edges onto `rows`, which the caller already has: one
// query per edge, however many rows there are.
pub fn (q OwnedPetQuery) nodes(rows []models.OwnedPet) ![]OwnedPetNode {
	mut nodes := rows.map(OwnedPetNode{
		graph:     q.graph
		owned_pet: it
	})
	if q.with_owner {
		found := q.load_owner(rows, q.owner_fns)!
		for mut node in nodes {
			// at most one each: the first, in the order of the query
			list := found[node.owned_pet.id.str()] or { [] }
			if list.len > 0 {
				node.owner = &UserNode{
					...list[0]
				}
			}
			node.loaded << 'owner'
		}
	}
	return nodes
}

// load_owner loads the `owner` of `rows`, keyed by each row's key.
fn (q OwnedPetQuery) load_owner(rows []models.OwnedPet, fns []fn (UserQuery) UserQuery) !map[string][]UserNode {
	mut sub := q.graph.users()
	for configure in fns {
		sub = configure(sub)
	}
	mut keys := []string{}
	for row in rows {
		keys << row.owner_id.str()
	}
	targets := sub.nodes(load.select_in[models.User](q.graph.client.conn, 'id', load.unique(keys),
		query: q.graph.client.prepare_edge_query('users', sub.query)!
	)!)!
	mut by_key := map[string]UserNode{}
	for target in targets {
		by_key[target.user.id.str()] = target
	}
	mut found := map[string][]UserNode{}
	for row in rows {
		if target := by_key[row.owner_id.str()] {
			found[row.id.str()] = [target]
		}
	}
	return found
}

// owner_or_err returns the `owner`: a `NotLoadedError` when the query didn't
// load it, a `NotFoundError` when the row has none.
pub fn (n OwnedPetNode) owner_or_err() !&UserNode {
	if 'owner' !in n.loaded {
		return NotLoadedError{
			edge: 'pet_owners.owner'
		}
	}
	if target := n.owner {
		return target
	}
	return NotFoundError{
		table: 'users'
	}
}

// query_owner starts a query of this row's `owner`, which matches
// nothing when the row has none.
pub fn (n OwnedPetNode) query_owner() UserQuery {
	key := n.owned_pet.owner_id
	return n.graph.users().where(load.eq('id', key))
}
